interface SmartClimate extends BasicClimate {
    void activateEcoMode();
}

abstract class ClimateUnit {
    protected String unitId;

    ClimateUnit(String unitId) {
        this.unitId = unitId;
    }

    public abstract void processCommand(double temp);
}

class Thermostat extends ClimateUnit implements SmartClimate {
    private double targetTemperature;

    Thermostat(String unitId) {
        super(unitId);
    }

    @Override
    public void setTemperature(double temp) {
        targetTemperature = temp;
    }

    @Override
    public void activateEcoMode() {
        System.out.println("Eco mode active for " + unitId);
    }

    @Override
    public void processCommand(double temp) {
        if (temp < 16.0 || temp > 30.0) {
            System.out.println("INVALID TEMP: " + temp);
        } else if (temp == 22.0) {
            activateEcoMode();
            System.out.println("OPTIMAL: Set to 22.0C for " + unitId);
        } else {
            setTemperature(temp);
            System.out.println("SUCCESS: Set to " + temp + "C for " + unitId);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        String unitId = sc.next();
        double temperature = sc.nextDouble();

        Thermostat thermostat = new Thermostat(unitId);
        thermostat.processCommand(temperature);

        sc.close();
    }
